import hashlib

def getDigest(input, algorithm):
    algorithms = {
        'md5': hashlib.md5,
        'sha256': hashlib.sha256,
        'sha512': hashlib.sha512
    }

    if algorithm.lower() not in algorithms:
        return "Invalid algorithm"

