import java.util.concurrent.atomic.AtomicInteger;

/**
 * Debug context holder interface. By default debugging context stores in ThreadLocal variable {@link DefaultDebugContextHolder}
 *
 * @author John Doe
 */
public interface DebugContextHolder {

    /**
     * Get debug context.
     *
     * @return DebugContext
     */
    DebugContext getDebugContext();
}

/**
 * Concrete implementation of DebugContextHolder using ThreadLocal for storing debugging context.
 */
public class DefaultDebugContextHolder implements DebugContextHolder {

    private static final ThreadLocal<DebugContext> debugContextThreadLocal = new ThreadLocal<DebugContext>() {
        @Override
        protected DebugContext initialValue() {
            return new DebugContext();
        }
    };

    @Override
    public DebugContext getDebugContext() {
        return debugContextThreadLocal.get();
    }
}

/**
 * Sample usage scenario to demonstrate the functionality of the debugging context holder in a multi-threaded environment.
 */
public class DebugContextDemo {

    public static void main(String[] args) {
        DefaultDebugContextHolder debugContextHolder = new DefaultDebugContextHolder();

        // Create and start multiple threads to access the debugging context
        for (int i = 0; i < 5; i++) {
            Thread thread = new Thread(() -> {
                DebugContext debugContext = debugContextHolder.getDebugContext();
                System.out.println("Thread " + Thread.currentThread().getId() + " - Debug ID: " + debugContext.getId());
            });
            thread.start();
        }
    }
}

/**
 * DebugContext class representing the debugging context.
 */
class DebugContext {
    private static final AtomicInteger idGenerator = new AtomicInteger(0);
    private int id;

    DebugContext() {
        this.id = idGenerator.incrementAndGet();
    }

    public int getId() {
        return id;
    }
}
