class Graph:
    def __init__(self, nodes: List[int], edges: List[Tuple[int, int]]):
        self.nodes = nodes
        self.edges = edges

    def flip_pairs(self, pairs: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
        flipped_pairs = []
        for i, j in pairs:
            if (i, j) in self.edges:
                flipped_pairs.append((j, i))
            elif (j, i) in self.edges:
                flipped_pairs.append((i, j))
        return flipped_pairs
```
